-- Athena saved query (Product_B2C_Intl)
-- ID: b4d5bfc8-6f94-438e-9e79-e3906c17446d
-- Name: RTC ASP - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp AS ( SELECT mri_session_id, rb_user_id, MAX( CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'COMFORT_SCORE_AB:V4') THEN 'V4' ELSE 'others' END ) AS exp_variant FROM user_interaction.search_route_details WHERE __time >= TIMESTAMP '2026-06-15 18:30:00' AND __time < TIMESTAMP '2026-06-22 18:30:00' AND os = 'Android' AND group_id > 0 AND country = 'IND' GROUP BY 1, 2 ), rtc_ops AS ( SELECT DISTINCT CAST(vendor_id AS BIGINT) AS operator_id FROM lis.bo_mappings WHERE is_rtc = 'RTC' ), -- one row per TIN (avoids fare/seat inflation from join fan-out) txn AS ( SELECT t.mri_session_id, t.rb_user_id, t.operator_id, t.tin, MAX(t.ticket_fare) AS ticket_fare, MAX(t.seat_count) AS seat_count FROM transaction.bus_ticket_events t INNER JOIN rtc_ops r ON t.operator_id = r.operator_id WHERE t.date_of_issue >= TIMESTAMP '2026-06-15 18:30:00' AND t.date_of_issue < TIMESTAMP '2026-06-22 18:30:00' AND t.sales_channel = 'RB:MOBILEWEB#droidapp' AND t.country_code = 'IND' AND t.event_class = 2 AND t.event_type = 101 AND t.tin IS NOT NULL AND t.tin NOT IN ('', 'null') AND t.seat_count > 0 AND t.ticket_fare IS NOT NULL GROUP BY 1, 2, 3, 4 ) -- SELECT -- t.operator_id, -- bo.bo_name AS rtc_name, -- COALESCE(s.exp_variant, 'null') AS exp_variant, -- COUNT(*) AS txn_count, -- SUM(t.seat_count) AS total_seats, -- ROUND(SUM(t.ticket_fare), 2) AS total_fare, -- ROUND(SUM(t.ticket_fare) * 1.0 / SUM(t.seat_count), 2) AS asp -- FROM txn t -- INNER JOIN srp s -- ON t.mri_session_id = s.mri_session_id -- AND t.rb_user_id = s.rb_user_id -- INNER JOIN lis.bo_mappings bo -- ON CAST(bo.vendor_id AS BIGINT) = t.operator_id -- AND bo.is_rtc = 'RTC' -- WHERE s.exp_variant IN ('V0', 'V1', 'V2') -- drop if you want V3/V4/others/null -- GROUP BY 1, 2, 3 -- ORDER BY txn_count DESC SELECT COALESCE(s.exp_variant, 'null') AS exp_variant, COUNT(*) AS txn_count, SUM(t.seat_count) AS total_seats, ROUND(SUM(t.ticket_fare), 2) AS total_fare, ROUND(SUM(t.ticket_fare) * 1.0 / SUM(t.seat_count), 2) AS asp FROM txn t INNER JOIN srp s ON t.mri_session_id = s.mri_session_id AND t.rb_user_id = s.rb_user_id WHERE s.exp_variant IN ('V0', 'V1', 'V2') GROUP BY 1 ORDER BY exp_variant
